example.code:
source "digitalocean" "example" {
  api_token = "REPLACE_WITH_TOKEN"
  image     = "ubuntu-20-04-x64"
  region    = "sfo1"
}

build {
  sources = ["source.digitalocean.example"]

  provisioner "ansible" {
    playbook_file = "./playbook.yml"
  }
}

provider "aws" {
  region = "us-west-2"
}

resource "aws_cloudformation_stack" "example" {
  name         = "example-stack"
  template_url = "https://my-bucket.s3.amazonaws.com/templates/my-template.yaml"
  parameters = {
    ParameterKey = "ParameterValue"
  }
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

provider "docker" {}

resource "docker_image" "nginx" {
  name = "nginx:latest"
}

resource "docker_container" "web" {
  name  = "web"
  image = docker_image.nginx.image_id
  ports {
    internal = 80
    external = 8080
  }
}

resource "hcp_vault_cluster" "example" {
  cluster_id = "vault-cluster"
  hvn_id     = hcp_hvn.example.hvn_id
  tier       = "standard_large"

  metrics_config {
    newrelic_account_id  = "newrelic_account_id"
    newrelic_license_key = "newrelic_license_key"
    newrelic_region      = "newrelic_region"
  }
}

terraform.syntax:
action "TYPE" "LABEL" {
  config {
    # provider-specific arguments
  }
}
terraform plan -invoke=action.TYPE.LABEL
terraform apply -invoke=action.TYPE.LABEL

example.code:
action "aws_lambda_invoke" "example" {
  config {
    function_name = "my_function"
    payload      = jsonencode({message = "hello"})
  }
}

# Preview the action only
terraform plan -invoke=action.aws_lambda_invoke.example

# Run the action
terraform apply -invoke=action.aws_lambda_invoke.example

terraform {
  required_providers {
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 3.0"
    }
  }
}

provider "kubernetes" {
  config_path = "~/.kube/config"
  config_context = "kind-terraform-learn"
}

resource "kubernetes_deployment_v1" "nginx" {
  metadata { name = "nginx" }
  spec {
    replicas = 2
    selector { match_labels = { app = "nginx" } }
    template {
      metadata { labels = { app = "nginx" } }
      spec {
        container {
          name  = "nginx"
          image = "nginx:stable-alpine-slim"
          port { container_port = 80 }
        }
      }
    }
  }
}

service_registration "kubernetes" {
  namespace = "my-namespace"
  pod_name  = "my-pod-name"
}
